import React, { Component, createContext } from '../../src';
import { render } from '../../src';
import { setupRerender } from '../../test-utils/src';
import { setupScratch, teardown } from '../../test/_util/helpers';

describe('repro', () => {
	let scratch, rerender;

	beforeEach(() => {
		scratch = setupScratch();
		rerender = setupRerender();
	});

	afterEach(() => {
		teardown(scratch);
	});

	it('supports multiple setState callbacks (cDM)', () => {
		const spy = sinon.spy();

		class App extends Component {
			constructor(props) {
				super(props);
				this.state = { count: 0 };
			}

			componentDidMount() {
				this.setState({ count: 1 }, spy);
				this.setState({ count: 2 }, spy);
			}

			render() {
				return <div />;
			}
		}

		render(<App />, scratch);

		rerender();
		expect(spy).to.have.been.calledTwice;
	});

	it('setState callback via subscription-like async', () => {
		const spy = sinon.spy();
		let fire;

		class App extends Component {
			componentDidMount() {
				this.setState({ test: true }, () => spy('test 1'));
				fire = () => {
					this.setState({ data: 'data' }, () => spy('test 3'));
					this.setState({ test: true }, () => spy('test 4'));
				};
			}
			render() {
				return <div>{this.state.data}</div>;
			}
		}

		render(<App />, scratch);
		rerender();
		fire();
		rerender();
		expect(spy).to.have.been.calledWith('test 3');
		expect(spy).to.have.been.calledWith('test 4');
	});
});

