import { expect } from 'chai';
import { createElement as h, render, Component, options } from '../../src';
import { setupRerender } from '../../test-utils/src';
import { setupScratch, teardown } from '../../test/_util/helpers';

describe('repro src', () => {
	let scratch, rerender;

	beforeEach(() => {
		scratch = setupScratch();
		rerender = setupRerender();
	});

	afterEach(() => {
		teardown(scratch);
	});

	it('supports multiple setState callbacks (cDM)', () => {
		const spy = [];

		class App extends Component {
			constructor(props) {
				super(props);
				this.state = { count: 0 };
			}

			componentDidMount() {
				this.setState({ count: 1 }, () => spy.push('a'));
				this.setState({ count: 2 }, () => spy.push('b'));
			}

			render() {
				return h('div');
			}
		}

		render(h(App), scratch);

		rerender();
		expect(spy).to.deep.equal(['a', 'b']);
	});

	it('setState callbacks after later subscription', () => {
		const spy = [];
		let fire;

		class App extends Component {
			componentDidMount() {
				this.setState({ test: true }, () => spy.push('test 1'));
				fire = () => {
					this.setState({ data: 'data' }, () => spy.push('test 3'));
					this.setState({ test: true }, () => spy.push('test 4'));
				};
			}
			render() {
				return h('div', null, this.state.data);
			}
		}

		render(h(App), scratch);
		rerender();
		fire();
		rerender();
		expect(spy).to.deep.equal(['test 3', 'test 4']);
	});

	it('setState callback with shouldComponentUpdate false', () => {
		const spy = [];

		class App extends Component {
			shouldComponentUpdate() {
				return false;
			}
			componentDidMount() {
				this.setState({ test: true }, () => spy.push('cb'));
			}
			render() {
				return h('div');
			}
		}

		render(h(App), scratch);
		rerender();
		expect(spy).to.deep.equal(['cb']);
	});
});

